$rows=$pdo->query("SELECT m.*,l.nama_lokasi FROM monitoring m JOIN lokasi l ON l.id=m.lokasi_id ORDER BY m.waktu_pantau DESC")->fetchAll();
$stats=$pdo->query("SELECT COUNT(*) total,SUM(status='Selesai') selesai,SUM(status='Dijadwalkan') aktif FROM penjadwalan")->fetch();
$trip=$pdo->query("SELECT COUNT(DISTINCT DATE(tanggal_angkut)) hari,COALESCE(SUM(m.berat),0) kg FROM penjadwalan p JOIN monitoring m ON m.id=p.monitoring_id WHERE p.status='Selesai'")->fetch();
